#include <stdio.h>
#include <string.h>

int main() {
    int n;
    scanf("%d", &n);

    // degree[v][bit] = parity of number of edges incident to v with that bit set
    int degree[100005][30];
    memset(degree, 0, sizeof(degree));

    for (int i = 0; i < n-1; i++) {
        int x, y, a;
        scanf("%d %d %d", &x, &y, &a);
        for (int b = 0; b < 30; b++) {
            if ((a >> b) & 1) {
                degree[x][b] ^= 1;
                degree[y][b] ^= 1;
            }
        }
    }

    long long ans = 0;
    for (int b = 0; b < 30; b++) {
        int cnt = 0;
        for (int v = 0; v < n; v++) cnt += degree[v][b];
        ans += cnt / 2;
    }

    printf("%lld\n", ans);
    return 0;
}

