typedef long long ll;

typedef struct {
    int to, next, id;
} Edge;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    if (N == 1) {
        printf("0\n");
        return 0;
    }

    int M = N - 1;
    int *X = (int*)malloc(sizeof(int) * M);
    int *Y = (int*)malloc(sizeof(int) * M);
    ll *A = (ll*)malloc(sizeof(ll) * M);

    for (int i = 0; i < M; i++) {
        scanf("%d %d %lld", &X[i], &Y[i], &A[i]);
    }

    int *head = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) head[i] = -1;

    Edge *edges = (Edge*)malloc(sizeof(Edge) * (2 * M));
    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        edges[ecnt].to = Y[i];
        edges[ecnt].id = i;
        edges[ecnt].next = head[X[i]];
        head[X[i]] = ecnt++;

        edges[ecnt].to = X[i];
        edges[ecnt].id = i;
        edges[ecnt].next = head[Y[i]];
        head[Y[i]] = ecnt++;
    }

    int *parent = (int*)malloc(sizeof(int) * N);
    int *pedge = (int*)malloc(sizeof(int) * N);
    int *order = (int*)malloc(sizeof(int) * N);
    int *stack = (int*)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++) parent[i] = -2;
    int top = 0, ord = 0;
    stack[top++] = 0;
    parent[0] = -1;

    while (top) {
        int v = stack[--top];
        order[ord++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (parent[u] != -2) continue;
            parent[u] = v;
            pedge[u] = edges[e].id;
            stack[top++] = u;
        }
    }

    ll *val = (ll*)malloc(sizeof(ll) * N);
    val[0] = 0;
    for (int i = 1; i < N; i++) {
        int v = order[i];
        val[v] = val[parent[v]] ^ A[pedge[v]];
    }

    ll *arr = (ll*)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) arr[i] = val[i];
    qsort(arr, N, sizeof(ll), cmp_ll);

    ll answer = 0;
    int i = 0;
    while (i < N) {
        int j = i + 1;
        while (j < N && arr[j] == arr[i]) j++;
        int cnt = j - i;
        if (cnt > 0) answer += (ll)(cnt - 1);
        i = j;
    }

    printf("%lld\n", answer);

    free(X);
    free(Y);
    free(A);
    free(head);
    free(edges);
    free(parent);
    free(pedge);
    free(order);
    free(stack);
    free(val);
    free(arr);

    return 0;
}

