/*
Key idea:
Let val[v] be XOR of edge values on the path from root(0) to v.
If we apply XOR by x on a path (u, v), then for every vertex t:
    val[t] changes only at the two endpoints in the "difference on tree" sense,
and the multiset of nonzero val[] can be paired by equal values.

In fact, making all edge values zero is equivalent to making all vertex potentials val[v] zero for v != 0
using operations that choose two vertices with the same current val and "cancel" them in one operation.
Therefore, for each XOR value z != 0 appearing cnt times among val[1..N-1], we need cnt/2 operations if cnt is even;
if any cnt is odd, impossible.

Why impossible for odd cnt:
Each operation toggles exactly two endpoints by the same x, so parity of occurrence count of each value is invariant mod 2.

Construction/minimum:
Each operation can eliminate at most two occurrences of the same nonzero value, so minimum is sum cnt/2.

Thus:
1) Root the tree at 0.
2) Compute prefix XOR val[v].
3) Count frequencies of val[v] for v = 1..N-1, ignoring 0.
4) If any frequency odd => print -1, else print sum(freq/2).

This runs in O(N).
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        List<Edge>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            long a = fs.nextLong();
            g[x].add(new Edge(y, a));
            g[y].add(new Edge(x, a));
        }

        long[] pref = new long[N];
        int[] parent = new int[N];
        Arrays.fill(parent, -1);

        int[] stack = new int[N];
        int top = 0;
        stack[top++] = 0;
        parent[0] = 0;

        while (top > 0) {
            int v = stack[--top];
            for (Edge e : g[v]) {
                if (parent[e.to] == -1) {
                    parent[e.to] = v;
                    pref[e.to] = pref[v] ^ e.w;
                    stack[top++] = e.to;
                }
            }
        }

        HashMap<Long, Integer> freq = new HashMap<>();
        for (int v = 1; v < N; v++) {
            long x = pref[v];
            if (x != 0) {
                freq.put(x, freq.getOrDefault(x, 0) + 1);
            }
        }

        long ans = 0;
        for (int c : freq.values()) {
            if ((c & 1) == 1) {
                System.out.println(-1);
                return;
            }
            ans += c / 2;
        }

        System.out.println(ans);
    }
}

