#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<pair<int,int>>> g(N);
    for (int i = 0; i < N - 1; ++i) {
        int x, y, a;
        cin >> x >> y >> a;
        g[x].push_back({y, a});
        g[y].push_back({x, a});
    }

    // Let val[v] be xor of edge values on path from root(0) to v.
    // An operation on path(u, v) with x toggles val[u] and val[v] by x,
    // all other val[*] unchanged.
    // So we need minimum operations to make all val[v] zero.
    // Since val[0] = 0 always, each operation can fix exactly two nonzero vertices,
    // hence answer = (# of vertices v with val[v] != 0) / 2.
    //
    // This is valid because xor of all val[v] over vertices of each connected
    // component of equal target can be paired arbitrarily in a tree using paths.

    vector<int> val(N, 0), parent(N, -1);
    queue<int> q;
    q.push(0);
    parent[0] = 0;

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (auto [to, w] : g[v]) {
            if (parent[to] != -1) continue;
            parent[to] = v;
            val[to] = val[v] ^ w;
            q.push(to);
        }
    }

    long long cnt = 0;
    for (int i = 0; i < N; ++i) {
        if (val[i] != 0) ++cnt;
    }

    cout << cnt / 2 << '\n';
    return 0;
}
